// User-created assets and structured battle sessions.
const assetKinds=[['equipment','장비'],['fighters','파이터 유형'],['skills','스킬·세트'],['gangTypes','갱 유형'],['tradingPosts','거래소'],['collections','컬렉션']];
function ensureAssets(){data.customAssets??={};for(const [k] of assetKinds)data.customAssets[k]??=[];data.assetTab??='equipment';for(const c of data.campaigns)c.sessions??=[]}ensureAssets();
function assetLabel(k){return assetKinds.find(x=>x[0]===k)?.[1]||k}function catalogPage(){ensureAssets();let k=data.assetTab,items=data.customAssets[k];return heading('CUSTOM ASSETS','사용자 정의 항목','나만의 장비, 파이터 유형, 스킬과 거래소를 구성하세요.',`<button class="btn primary" data-catalog="new">＋ ${assetLabel(k)} 만들기</button>`)+`<div class="tabs">${assetKinds.map(([v,l])=>`<button data-catalog-tab="${v}" class="${k===v?'active':''}">${l} <small>${data.customAssets[v].length}</small></button>`).join('')}</div>${items.length?`<div class="grid">${items.map(a=>`<article class="card">${chip(assetLabel(k),'gold')}<h3>${esc(a.name)}</h3><p>${esc(a.description||a.subtype||'설명 없음')}</p>${a.cost!==undefined?`<div class="meta"><span><b>${fmt(a.cost)}</b>비용</span>${a.tradePoints?`<span><b>${esc(a.tradePoints)}</b>거래 포인트</span>`:''}</div>`:''}<div class="actions"><button class="btn small" data-catalog="edit" data-id="${a.id}">수정</button><button class="btn small danger" data-catalog="delete" data-id="${a.id}">삭제</button></div></article>`).join('')}</div>`:empty('▤',`${assetLabel(k)} 항목이 없습니다`,'사용자 정의 항목을 추가해 명단과 장비 목록에 활용하세요.',`<button class="btn primary" data-catalog="new">항목 만들기</button>`)}`}
const originalRender=render;render=function(){originalRender();let nav=$('.nav');if(nav){let button=document.createElement('button');button.setAttribute('data-catalog-nav','');button.className=data.view==='catalog'?'active':'';button.innerHTML='<span class="ico">▤</span>사용자 자산';nav.insertBefore(button,nav.lastElementChild)}if(data.view==='catalog'){$('.content').innerHTML=catalogPage();$('.crumb strong').textContent='사용자 자산'}};
function assetFields(kind,a){let common=field('name','이름',a?.name,'text','required');if(kind==='equipment')return common+select('equipmentType','장비 유형',['Weapon','Wargear','Armour','Ammunition','Accessory','Other'],a?.equipmentType||'Weapon')+field('category','분류',a?.category||'')+field('tradePoints','거래 포인트',a?.tradePoints||'')+field('cost','비용 (cr)',a?.cost??0,'number','min="0"')+`<label>소모품<select name="consumable"><option value="no" ${a?.consumable!=='yes'?'selected':''}>아니요</option><option value="yes" ${a?.consumable==='yes'?'selected':''}>예</option></select></label>`+textarea('description','설명',a?.description);if(kind==='fighters')return common+field('subtype','계급 / 유형',a?.subtype||'Ganger')+field('cost','기본 비용 (cr)',a?.cost??0,'number','min="0"')+textarea('description','설명',a?.description);if(kind==='gangTypes')return common+field('subtype','하위 유형',a?.subtype||'')+field('cost','시작 크레딧',a?.cost??1000,'number','min="0"')+textarea('description','설명',a?.description);return common+textarea('description','설명',a?.description)}
function editAsset(a){let kind=data.assetTab;formModal(`${assetLabel(kind)} ${a?'수정':'만들기'}`,assetFields(kind,a),v=>{let value={...v,cost:v.cost===undefined?undefined:n(v.cost)};if(a)Object.assign(a,value);else data.customAssets[kind].push({id:id(),...value});save()})}
const originalAddEquipment=addEquipment;addEquipment=function(f,stash=false){ensureAssets();let g=gang(),list=data.customAssets.equipment;let fields=select('preset','사용자 장비',[['','직접 입력'],...list.map(e=>[e.id,e.name])],'')+field('name','장비 이름','','text','required')+field('cost','비용 (cr)',0,'number','min="0"')+select('destination','보관 위치',[['fighter','파이터'],['stash','갱 창고']],stash?'stash':'fighter')+`<label class="wide"><input type="checkbox" name="spend" value="yes" style="width:auto"> 갱 크레딧에서 비용 차감</label>`;formModal('장비 등록',fields,v=>{let e={id:id(),name:v.name,cost:n(v.cost),presetId:v.preset||''};if(v.destination==='stash'||!f)g.stash.push(e);else f.equipment.push(e);if(v.spend==='yes')g.credits=Math.max(0,g.credits-e.cost);log(g,`${e.name} 장비를 등록했습니다.`);save()});$('#modal-form [name="preset"]').addEventListener('change',ev=>{let x=list.find(a=>a.id===ev.target.value);if(x){$('#modal-form [name="name"]').value=x.name;$('#modal-form [name="cost"]').value=x.cost||0}})};
const originalEditFighter=editFighter;editFighter=function(f){if(f)return originalEditFighter(f);ensureAssets();let g=gang(),list=data.customAssets.fighters;let fields=select('preset','사용자 파이터 유형',[['','직접 입력'],...list.map(x=>[x.id,x.name])],'')+field('name','이름','','text','required')+field('type','유형 / 계급','Ganger','text','required')+field('cost','기본 비용 (cr)',0,'number','min="0"')+select('status','상태',['Active','In Recovery','Captured','Retired','Dead','Enslaved','Starved'],'Active')+field('xp','경험치',0,'number','min="0"')+field('kills','처치 수',0,'number','min="0"')+textarea('notes','메모');formModal('파이터 추가',fields,v=>{let f={id:id(),name:v.name,type:v.type,cost:n(v.cost),status:v.status,xp:n(v.xp),kills:n(v.kills),stats:{...baseStats},equipment:[],skills:[],effects:[],notes:v.notes};g.fighters.push(f);log(g,`${f.name} 파이터를 추가했습니다.`);save()});$('#modal-form [name="preset"]').addEventListener('change',ev=>{let x=list.find(a=>a.id===ev.target.value);if(x){$('#modal-form [name="type"]').value=x.name;$('#modal-form [name="cost"]').value=x.cost||0}})};
function sessionSection(c){c.sessions??=[];return `<div class="toolbar" style="margin-top:24px"><h2 class="section-title">전투 세션</h2><button class="btn primary" data-session="new">＋ 새 전투 세션</button></div>${c.sessions.length?`<div class="grid">${[...c.sessions].reverse().map(s=>`<article class="card">${chip(s.status||'Active',s.status==='Active'?'gold':'')}<h3>${esc(s.scenario||'이름 없는 시나리오')}</h3><p>${esc(s.date)} · ${esc(data.gangs.find(g=>g.id===s.opponent)?.name||'상대 갱 미정')}</p><div class="meta"><span><b>${esc(s.cycle||'—')}</b>사이클</span><span><b>${esc(s.deployment||'—')}</b>배치</span></div><button class="btn small" data-session="detail" data-id="${s.id}">세션 열기</button></article>`).join('')}</div>`:empty('⚔','전투 세션이 없습니다','상대 갱, 배치, 목표와 크루를 정하고 전투를 진행하세요.')}`}
const oldBattlesTab=battlesTab;battlesTab=function(c){return sessionSection(c)+`<h2 class="section-title" style="margin-top:26px">완료된 전투 기록</h2>`+oldBattlesTab(c)};
function packTab(c){return `<div class="split"><article class="card"><h3>캠페인 팩</h3><p>${esc(c.description||'설명 없음')}</p><div class="mini-row">에디션 <strong>${esc(c.edition)}</strong></div><div class="mini-row">상태 <strong>${esc(c.phase)}</strong></div><div class="mini-row">참가 갱 <strong>${c.members.length}</strong></div><h3>캠페인 스토리</h3><p style="white-space:pre-wrap">${esc(c.notes||'기록 없음')}</p></article><article class="card"><h3>하우스 룰</h3><p style="white-space:pre-wrap">${esc(c.houseRules||'기록 없음')}</p><button class="btn small" data-ext="edit-house-rules">수정</button></article></div>`}
campaignPage=function(){const c=campaign();if(!c)return campaignsPage();campaignExtras(c);c.sessions??=[];const tabs=[['members','캠페인'],['territories','영토'],['battles','전투'],['pack','캠페인 팩'],['campaign-notes','노트'],['map','지도'],['triumphs','성과']];const ct=data.campaignTab||'members';return heading('CAMPAIGN RECORD',esc(c.name),`${esc(c.edition)} · ${esc(c.phase)}`,btn('캠페인 수정','edit-campaign')+btn('삭제','delete-campaign','danger'))+`<div class="stats">${stat('참가 갱',c.members.length,'플레이어 연결')}${stat('영토',c.territories.length,'등록된 영토')}${stat('전투',c.battles.length,'기록된 전투')}${stat('최고 평점',fmt(Math.max(0,...c.members.map(m=>rating(data.gangs.find(g=>g.id===m.gangId))))),'참가 갱 기준')}</div><div class="tabs">${tabs.map(([v,t])=>`<button data-campaign-tab="${v}" class="${ct===v?'active':''}">${t}</button>`).join('')}</div>${({members:()=>membersTab(c),territories:()=>territoriesTab(c),battles:()=>battlesTab(c),pack:()=>packTab(c),'campaign-notes':()=>campaignNotesTab(c),map:()=>mapTab(c),triumphs:()=>triumphsTab(c)})[ct]?.()||membersTab(c)}`};
function sessionForm(s){let c=campaign();c.sessions??=[];formModal(s?'전투 세션 수정':'새 전투 세션',field('scenario','시나리오',s?.scenario||'','text','required')+field('date','날짜',s?.date||new Date().toISOString().slice(0,10),'date','required')+field('cycle','사이클',s?.cycle||'')+select('opponent','상대 갱',gangOptions('',true),s?.opponent||'')+field('deployment','배치',s?.deployment||'')+field('objective','목표',s?.objective||'')+field('crew','크루',s?.crew||'')+textarea('notes','전투 메모',s?.notes),v=>{if(s)Object.assign(s,v);else c.sessions.push({id:id(),...v,status:'Active',winner:'',result:''});save()})}
function sessionDetail(s){showModal('전투 세션',`<p>${chip(s.status,s.status==='Active'?'gold':'')} · ${esc(s.date)} · 사이클 ${esc(s.cycle||'—')}</p><h3>${esc(s.scenario)}</h3><div class="mini-list"><div class="mini-row">상대 갱 <strong>${esc(data.gangs.find(g=>g.id===s.opponent)?.name||'미정')}</strong></div><div class="mini-row">배치 <strong>${esc(s.deployment||'미정')}</strong></div><div class="mini-row">목표 <strong>${esc(s.objective||'미정')}</strong></div><div class="mini-row">크루 <strong>${esc(s.crew||'미정')}</strong></div></div><p style="white-space:pre-wrap">${esc(s.notes||'')}</p><div class="actions"><button class="btn small" data-session="edit" data-id="${s.id}">수정</button>${s.status==='Active'?`<button class="btn small primary" data-session="complete" data-id="${s.id}">전투 완료</button>`:''}<button class="btn small danger" data-session="delete" data-id="${s.id}">삭제</button></div>`,'닫기',()=>true)}
function completeSession(s){let c=campaign();formModal('전투 결과',select('winner','승자',gangOptions('',true))+field('result','결과 / 점수',s.result||'')+textarea('notes','전투 보고',s.notes||''),v=>{s.status='Completed';s.winner=v.winner;s.result=v.result;s.notes=v.notes;c.battles.push({id:id(),name:s.scenario,date:s.date,winner:v.winner,notes:v.notes,sessionId:s.id});save()})}
document.addEventListener('click',e=>{let t=e.target.closest('[data-catalog-nav],[data-catalog-tab],[data-catalog],[data-session]');if(!t)return;e.stopImmediatePropagation();let d=t.dataset;if('catalogNav'in d){data.view='catalog';save();return}if(d.catalogTab){data.assetTab=d.catalogTab;save();return}if(d.catalog){ensureAssets();let list=data.customAssets[data.assetTab],a=list.find(x=>x.id===d.id);if(d.catalog==='new')editAsset();else if(d.catalog==='edit')editAsset(a);else if(d.catalog==='delete')confirmDelete('항목 삭제',`${esc(a.name)}을(를) 삭제할까요?`,()=>{data.customAssets[data.assetTab]=list.filter(x=>x.id!==a.id);save()});return}if(d.session){let c=campaign();c.sessions??=[];let s=c.sessions.find(x=>x.id===d.id);if(d.session==='new')sessionForm();else if(d.session==='detail')sessionDetail(s);else if(d.session==='edit'){closeModal();sessionForm(s)}else if(d.session==='complete'){closeModal();completeSession(s)}else if(d.session==='delete'){closeModal();confirmDelete('전투 세션 삭제','이 전투 세션을 삭제할까요?',()=>{c.sessions=c.sessions.filter(x=>x.id!==s.id);save()})}}},true);
render();
